fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0;
    let mut right = v.len();
    
    while left < right {
        let mid = left + (right - left) / 2;
        
        if v[mid] == k {
            return mid;
        } else if v[mid] < k {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    
    // Since we assume k exists in the array, we should never reach this point
    // But we need to return something to satisfy the compiler
    left
}